using System;

public class Program
{
    public static void Main()
    {
        int a = int.Parse(Console.ReadLine());
        int b = int.Parse(Console.ReadLine());
        int previous = a + b;
        for (int i = 2; i <= 218; i++)
        {
            a = int.Parse(Console.ReadLine());
            b = int.Parse(Console.ReadLine());
            int sum = a + b;
            if (sum < previous)
                Console.WriteLine("Smaller");
            previous = sum;
        }
    }
}

